/**
 * Offline USGS 3DEP elevation snapshots for Tucson and Ann Arbor.
 *
 * Heights are quantized unsigned 16-bit values. Rows run north to south and columns
 * run west to east. Use sampleTerrainHeightfield() or one of the named samplers for
 * fast bilinear lookup; no network request is made at runtime.
 */

const NORMALIZED_MAX = 65535;

function decodeUint16Base64(encoded) {
  let binary;
  if (typeof atob === 'function') binary = atob(encoded);
  else if (typeof Buffer !== 'undefined') binary = Buffer.from(encoded, 'base64').toString('latin1');
  else throw new Error('This environment has no base64 decoder');
  const result = new Uint16Array(binary.length / 2);
  for (let i = 0; i < result.length; i += 1) {
    const offset = i * 2;
    result[i] = binary.charCodeAt(offset) | (binary.charCodeAt(offset + 1) << 8);
  }
  return result;
}

function makeTerrain({ id, width, height, encoded, west, east, south, north, minElevationMeters, maxElevationMeters, sourceResolution }) {
  return {
    id,
    width,
    height,
    heights: decodeUint16Base64(encoded),
    west,
    east,
    south,
    north,
    minElevationMeters,
    maxElevationMeters,
    sourceResolution,
  };
}

const clamp01 = (value) => Math.max(0, Math.min(1, value));

function smoothstep(edge0, edge1, value) {
  if (edge1 <= edge0) return value >= edge1 ? 1 : 0;
  const t = clamp01((value - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
}

/**
 * Bilinearly sample a normalized heightfield. u=0/v=0 is northwest and
 * u=1/v=1 is southeast. Outside coordinates return 0. feather is the
 * normalized edge width used to fade a patch smoothly into surrounding ground.
 */
export function sampleTerrainHeightfield(field, u, v, feather = 0.08) {
  if (!field || !Number.isFinite(u) || !Number.isFinite(v) || u < 0 || u > 1 || v < 0 || v > 1) return 0;
  const gx = u * (field.width - 1);
  const gy = v * (field.height - 1);
  const x0 = Math.floor(gx);
  const y0 = Math.floor(gy);
  const x1 = Math.min(field.width - 1, x0 + 1);
  const y1 = Math.min(field.height - 1, y0 + 1);
  const tx = gx - x0;
  const ty = gy - y0;
  const row0 = y0 * field.width;
  const row1 = y1 * field.width;
  const top = field.heights[row0 + x0] * (1 - tx) + field.heights[row0 + x1] * tx;
  const bottom = field.heights[row1 + x0] * (1 - tx) + field.heights[row1 + x1] * tx;
  const raw = (top * (1 - ty) + bottom * ty) / NORMALIZED_MAX;
  const edge = Math.max(0, Math.min(0.5, Number(feather) || 0));
  if (edge === 0) return raw;
  const distanceToEdge = Math.min(u, 1 - u, v, 1 - v);
  return raw * smoothstep(0, edge, distanceToEdge);
}

export const TUCSON_CATALINA_TERRAIN = makeTerrain({
  id: 'tucson-catalina-3dep-centered',
  width: 129, height: 129, encoded: '',
  west: -110.88, east: -110.7, south: 32.35, north: 32.53,
  minElevationMeters: 923.9874877929688, maxElevationMeters: 2778.518310546875,
  sourceResolution: '129 x 129 export from USGS 3DEP dynamic DEM service',
});

export const ANN_ARBOR_CAMPUS_TERRAIN = makeTerrain({
  id: 'ann-arbor-campus-3dep',
  width: 65, height: 65, encoded: '',
  west: -83.8, east: -83.67, south: 42.24, north: 42.34,
  minElevationMeters: 227.49058532714844, maxElevationMeters: 321.9293212890625,
  sourceResolution: '65 x 65 export from USGS 3DEP dynamic DEM service',
});

export const ANN_ARBOR_WEST_FARM_TERRAIN = makeTerrain({
  id: 'ann-arbor-west-farm-3dep',
  width: 65, height: 65, encoded: '',
  west: -83.95, east: -83.86, south: 42.25, north: 42.32,
  minElevationMeters: 258.6297912597656, maxElevationMeters: 289.6836853027344,
  sourceResolution: '65 x 65 export from USGS 3DEP dynamic DEM service',
});

export const TUCSON_CATALINA_HEIGHTS = TUCSON_CATALINA_TERRAIN.heights;
export const TUCSON_CATALINA_GRID_SIZE = TUCSON_CATALINA_TERRAIN.width;
export const ANN_ARBOR_CAMPUS_HEIGHTS = ANN_ARBOR_CAMPUS_TERRAIN.heights;
export const ANN_ARBOR_WEST_FARM_HEIGHTS = ANN_ARBOR_WEST_FARM_TERRAIN.heights;

export const sampleTucsonCatalinaHeight = (u, v, feather = 0.08) => sampleTerrainHeightfield(TUCSON_CATALINA_TERRAIN, u, v, feather);
export const sampleTucsonTerrain = sampleTucsonCatalinaHeight;
export const sampleAnnArborCampusHeight = (u, v, feather = 0.08) => sampleTerrainHeightfield(ANN_ARBOR_CAMPUS_TERRAIN, u, v, feather);
export const sampleAnnArborWestFarmHeight = (u, v, feather = 0.08) => sampleTerrainHeightfield(ANN_ARBOR_WEST_FARM_TERRAIN, u, v, feather);

export const GROUND_ELEVATION_TERRAINS = {
  tucsonCatalina: TUCSON_CATALINA_TERRAIN,
  annArborCampus: ANN_ARBOR_CAMPUS_TERRAIN,
  annArborWestFarm: ANN_ARBOR_WEST_FARM_TERRAIN,
};
